WITH parsed AS (SELECT id, service, log_ts, level, context, context['region'] AS region, SIZE(context) AS num_context FROM app_logs) SELECT id, service, log_ts, level, context, region, num_context, NTILE(4) OVER (ORDER BY num_context DESC, id) AS num_context_bucket, AVG(num_context) OVER (PARTITION BY level ORDER BY num_context, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS num_context_avg_6_prior FROM parsed;
